```javascript
import { uv, mix, smoothstep, length, uniform } from 'three/tsl';
import { 
  Group, 
  Mesh, 
  TorusKnotGeometry, 
  CylinderGeometry, 
  PlaneGeometry,
  DirectionalLight,
  AmbientLight,
  Color,
  MeshPhysicalNodeMaterial,
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial
} from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  const loadedTextures = [];
  const timelines = [];

  // Torus knot with brushed metal PBR material
  const knotMaterial = new THREE.MeshPhysicalNodeMaterial({
    color: new THREE.Color(0xe8ecf2),
    metalness: 0.55,
    roughness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35,
    anisotropy: 0.9,
    anisotropyRotation: Math.PI / 2
  });

  ctx.textureLoader.loadTexture('/prism-assets/chrome/brushed-metal.map.png').then(metalTexture => {
    knotMaterial.roughnessMap = metalTexture;
    knotMaterial.needsUpdate = true;
    loadedTextures.push(metalTexture);
  });

  const knot = new THREE.Mesh(
    new THREE.TorusKnotGeometry(0.7, 0.22, 220, 36),
    knotMaterial
  );
  knot.position.set(0, 0.4, 0);
  group.add(knot);

  // Cylindrical pedestal (top face at y=-0.35, so center at -0.6)
  const pedestalMaterial = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color(0x14141a),
    roughness: 0.7,
    metalness: 0.35
  });

  const pedestal = new THREE.Mesh(
    new THREE.CylinderGeometry(1.1, 1.1, 0.5, 64),
    pedestalMaterial
  );
  pedestal.position.y = -0.6;
  group.add(pedestal);

  // Contact shadow with radial gradient
  const shadowGeometry = new THREE.PlaneGeometry(3.0, 3.0);
  const shadowMaterial = new THREE.MeshBasicNodeMaterial({
    transparent: true
  });

  const shadowUV = uv();
  const shadowCenter = shadowUV.sub(0.5).mul(2);
  const shadowDist = length(shadowCenter);
  const shadowOpacity = mix(0.6, 0, smoothstep(0, 0.4, shadowDist));

  shadowMaterial.colorNode = uniform(new THREE.Color(0x000000));
  shadowMaterial.opacityNode = shadowOpacity;

  const shadow = new THREE.Mesh(shadowGeometry, shadowMaterial);
  shadow.position.set(0, -0.36, 0.01);
  shadow.rotation.x = Math.PI / 2;
  group.add(shadow);

  // Backdrop with vertical gradient (stops at 0→0x0b0b10, 0.7→0x101017, 1→0x16161d)
  const backdropGeometry = new THREE.PlaneGeometry(7, 6);
  const backdropMaterial = new THREE.MeshBasicNodeMaterial();

  const backdropUV = uv();
  const gradY = backdropUV.y;

  const col0 = uniform(new THREE.Color(0x0b0b10));
  const col1 = uniform(new THREE.Color(0x101017));
  const col2 = uniform(new THREE.Color(0x16161d));

  const lowerGrad = mix(col0, col1, gradY.div(0.7));
  const upperGrad = mix(col1, col2, gradY.sub(0.7).div(0.3));
  const gradSelector = smoothstep(0.69, 0.71, gradY);
  const backdropColor = mix(lowerGrad, upperGrad, gradSelector);

  backdropMaterial.colorNode = backdropColor;

  const backdrop = new THREE.Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.z = -3;
  group.add(backdrop);

  // Studio lighting: key, rim, ambient
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2.5, 2.5, 2);
  group.add(keyLight);

  const rimLight = new THREE.DirectionalLight(0xffccbb, 0.8);
  rimLight.position.set(-2.5, 1.5, -2);
  group.add(rimLight);

  const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
  group.add(ambientLight);

  // Text: headline 1.2 units below center, caption 1.6 units below center
  const headline = ctx.fontAtlas.createText('Material study 03', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'center'
  });
  headline.position.set(0, -1.2, 0);
  group.add(headline);

  const caption = ctx.fontAtlas.createText('GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 1.44
  });
  caption.position.set(0, -1.6, 0);
  group.add(caption);

  // Apply orbit primitive: knot rotates at 0.1 rad/s, camera drifts radius 0.4
  const orbitResult = ctx.primitives['orbit'](knot, {
    speed: 0.1,
    radius: 0.4
  });
  if (orbitResult?.timeline) {
    timelines.push(orbitResult.timeline);
  }

  // Cleanup: dispose geometries, materials, textures, kill timelines
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl?.kill?.());
    loadedTextures.forEach(tex => tex.dispose());
    group.traverse(obj => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material?.dispose) obj.material.dispose();
    });
  };

  return group;
}
